#!/bin/bash
fail=0
t=$(mktemp); printf '# h\n' > "$t"
# expect_exit DESC EXPECTED ARGS...: run book.sh with the given times and check the exit code.
expect_exit() {
  local desc=$1 want=$2; shift 2
  BOOKINGS=$t bash src/book.sh aoi 2026-01-05 "$@" x >/dev/null 2>&1; local got=$?
  [ "$got" = "$want" ] || { echo "$desc: exit $got, expected $want"; fail=1; }
}
expect_exit "bad start time" 2 9am 10:00
expect_exit "bad end time" 2 10:00 10am
expect_exit "bad end time (no minutes)" 2 10:00 1000
expect_exit "valid times" 0 10:00 11:00
[ "$(grep -vc '^#' "$t")" = 1 ] || { echo "rejected bookings were stored (or the valid one was not)"; fail=1; }
rm -f "$t"; exit $fail

